$q=db()->prepare("SELECT e.*,a.display_name agent_name FROM task_evidence e LEFT JOIN agents a ON a.id=e.agent_id WHERE e.project_id=? ORDER BY e.id DESC LIMIT 120");$q->execute([$id]);$evidence=$q->fetchAll();
