$q=db()->prepare("SELECT * FROM project_stage_events WHERE project_id=? ORDER BY id DESC LIMIT 100");$q->execute([$id]);$stages=$q->fetchAll();
$q=db()->prepare("SELECT * FROM backups WHERE project_id=? ORDER BY id DESC LIMIT 50");$q->execute([$id]);$backups=$q->fetchAll();
$q=db()->prepare("SELECT * FROM deployments WHERE project_id=? ORDER BY id DESC LIMIT 50");$q->execute([$id]);$deploys=$q->fetchAll();
$q=db()->prepare("SELECT * FROM project_memory WHERE project_id=? AND active=1 ORDER BY id DESC LIMIT 60");$q->execute([$id]);$memory=$q->fetchAll();
